@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=DM+Sans:wght@400;500;600;700;800&family=Space+Grotesk:wght@500;600;700&display=swap');
:root{color-scheme:dark;--ink:#f4f0e5;--muted:#a9b5b5;--gold:#f2c46d;--teal:#78dac2}
*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#0d1722;color:var(--ink);font-family:'DM Sans',sans-serif}body{display:grid;place-items:center;background:radial-gradient(ellipse at 50% 40%,#20323d 0%,#101a27 70%)}#game-shell{position:relative;width:min(100vw,177.78vh);height:min(100vh,56.25vw);max-width:1280px;max-height:720px;aspect-ratio:16/9;overflow:hidden;border:1px solid #42535b;border-radius:12px;box-shadow:0 22px 70px #0009;background:#15232c}canvas{display:block;width:100%;height:100%;image-rendering:pixelated;touch-action:none}#toast{position:absolute;top:17%;left:50%;transform:translate(-50%,-10px);padding:11px 18px;border:1px solid #ffffff27;border-radius:8px;background:#10212beF;color:#f5d894;font:500 13px 'DM Mono',monospace;letter-spacing:.04em;opacity:0;transition:.25s;pointer-events:none;white-space:nowrap;z-index:5}#toast.show{opacity:1;transform:translate(-50%,0)}#touch-controls{position:absolute;inset:auto 0 0;display:none;justify-content:space-between;align-items:end;padding:12px 14px;pointer-events:none}.dpad,.touch-actions{display:flex;gap:8px;pointer-events:auto}.touch-actions{align-items:flex-end}.dpad button,.touch-actions button{height:48px;min-width:52px;padding:0 13px;color:#eff4e8;background:#12242bd9;border:1px solid #95d1bd77;border-radius:12px;font:700 12px 'DM Mono',monospace;touch-action:none;box-shadow:0 4px 12px #0005}.dpad button{font-size:18px}.screen-reader{position:absolute;left:-10000px}@media (pointer:coarse),(max-width:800px){#touch-controls{display:flex}#game-shell{border-radius:0;border:0}}@media(max-height:460px){#touch-controls{padding:5px 10px}.dpad button,.touch-actions button{height:39px;min-width:45px}}

(()=>{
'use strict';
const canvas=document.getElementById('game'),ctx=canvas.getContext('2d'),W=960,H=540;
ctx.imageSmoothingEnabled=false;
const toastEl=document.getElementById('toast');
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v)),rand=(a,b)=>a+Math.random()*(b-a),pick=a=>a[Math.floor(Math.random()*a.length)];
const keys={};let mode='title',overlay='',toastTimer=0,last=0,worldTime=0,shake=0;
const species={mossling:{name:'Mossling',type:'Verdant',color:'#88c67a',dark:'#426d56',hp:92,atk:19,skill:'Briar Burst',emoji:'✦'},cinderkit:{name:'Cinderkit',type:'Ember',color:'#f59b69',dark:'#a74d48',hp:78,atk:24,skill:'Flare Pounce',emoji:'✹'},tidepup:{name:'Tidepup',type:'Tide',color:'#77bfdd',dark:'#3c718f',hp:100,atk:16,skill:'Mooncurrent',emoji:'≈'},gloamoth:{name:'Gloamoth',type:'Gloam',color:'#b59be5',dark:'#695492',hp:84,atk:21,skill:'Night Dust',emoji:'✧'},craglet:{name:'Craglet',type:'Stone',color:'#d8ad78',dark:'#85684f',hp:115,atk:15,skill:'Quake Knuckle',emoji:'⬟'},thornox:{name:'Thornox',type:'Verdant',color:'#b6c66b',dark:'#657241',hp:132,atk:22,skill:'Wild Trample',emoji:'♢'},hollow:{name:'Hollow Stag',type:'Gloam',color:'#b699cf',dark:'#51415f',hp:280,atk:28,skill:'Eclipse Horn',emoji:'♜'}};
const makeMon=(id,level=1)=>{const s=species[id];return{id,name:s.name,type:s.type,color:s.color,dark:s.dark,level,max:s.hp+level*8,hp:s.hp+level*8,atk:s.atk+level*2,skill:s.skill,emoji:s.emoji,xp:0}};
const fresh=()=>({player:{x:120,y:0,vy:0,dir:1,onGround:false},party:[makeMon('mossling',2),makeMon('cinderkit',1),makeMon('tidepup',1)],shards:4,essence:0,coins:25,unlocks:{dash:false,break:false},checkpoint:120,wonBoss:false,seen:{},bestiary:[],facing:1});
let save;try{save=JSON.parse(localStorage.getItem('wilderkin-save'))||fresh()}catch{save=fresh()};
let player=save.player,party=save.party.map(m=>({...m})),shards=save.shards,essence=save.essence,coins=save.coins,unlocks=save.unlocks||{dash:false,break:false},checkpoint=save.checkpoint||120,wonBoss=save.wonBoss||false,seen=save.seen||{},bestiary=save.bestiary||[];
const worldW=3900,groundY=430;
const regions=[{start:0,end:1060,name:'SUNDEW MEADOW',sub:'The First Green',sky:['#b8d9c2','#e8d5a5'],accent:'#8ab58a',plant:'#628b72'},{start:1060,end:2140,name:'GLASSROOT CAVERN',sub:'Below the roots',sky:['#5f7c82','#302f48'],accent:'#75b5ac',plant:'#477879'},{start:2140,end:3030,name:'MOONFALL MARSH',sub:'Where the light sleeps',sky:['#465b72','#242c46'],accent:'#a194c6',plant:'#526678'},{start:3030,end:3900,name:'CROWN OF THORNS',sub:'The old sanctuary',sky:['#786f78','#2c3041'],accent:'#d8ae6d',plant:'#7b7156'}];
const zoneAt=x=>regions.findIndex(r=>x>=r.start&&x<r.end)||0;
const solids=[{x:920,w:110,h:130,kind:'ledge'},{x:1460,w:150,h:140,kind:'ledge'},{x:1830,w:110,h:200,kind:'ledge'},{x:2370,w:140,h:130,kind:'ledge'},{x:2820,w:180,h:160,kind:'ledge'}];
const gates=[{x:1060,kind:'dash',label:'WIND SEAL'},{x:2140,kind:'break',label:'ROOT SEAL'}];
const pickups=[{x:420,y:0,id:'shard',got:false},{x:790,y:0,id:'chest',got:false},{x:1360,y:0,id:'shard',got:false},{x:1740,y:0,id:'chest',got:false},{x:2500,y:0,id:'shard',got:false},{x:3210,y:0,id:'chest',got:false}];
const shrines=[{x:130,label:'WAYFARER SHRINE'},{x:1150,label:'ROOTBOUND SHRINE'},{x:2230,label:'MISTVEIL SHRINE'},{x:3140,label:'SANCTUARY SHRINE'}];
const flora=Array.from({length:190},(_,i)=>({x:i*23+rand(-12,12),h:rand(15,76),w:rand(8,24),seed:rand(0,20)}));
function persist(){save={player,party,shards,essence,coins,unlocks,checkpoint,wonBoss,seen,bestiary};try{localStorage.setItem('wilderkin-save',JSON.stringify(save))}catch{}}
function toast(s){toastEl.textContent=s;toastEl.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toastEl.classList.remove('show'),2100)}
function region(){return regions[zoneAt(player.x)]}
function startGame(){if(mode==='title'){mode='explore';toast('The wilds are waiting. Follow the lanterns.');persist()}}
function button(x,y,w,h,label,fn,opts={}){ctx.fillStyle=opts.fill||'#233a3b';roundRect(x,y,w,h,7,true,false);ctx.strokeStyle=opts.stroke||'#d8cc9c66';ctx.lineWidth=1;roundRect(x,y,w,h,7,false,true);ctx.fillStyle=opts.color||'#f3edda';ctx.font=`${opts.bold?'700':'500'} ${opts.size||13}px "DM Sans", sans-serif`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(label,x+w/2,y+h/2);if(mouse.clicked&&mouse.x>=x&&mouse.x<=x+w&&mouse.y>=y&&mouse.y<=y+h)fn()}
const mouse={x:0,y:0,clicked:false};
canvas.addEventListener('pointermove',e=>{const r=canvas.getBoundingClientRect();mouse.x=(e.clientX-r.left)*W/r.width;mouse.y=(e.clientY-r.top)*H/r.height});canvas.addEventListener('pointerdown',e=>{const r=canvas.getBoundingClientRect();mouse.x=(e.clientX-r.left)*W/r.width;mouse.y=(e.clientY-r.top)*H/r.height;mouse.clicked=true;if(mode==='title')startGame()});
window.addEventListener('keydown',e=>{const k=e.key.toLowerCase();if([' ','arrowleft','arrowright','arrowup','arrowdown'].includes(k))e.preventDefault();keys[k]=true;if(k==='escape'||k==='tab'){e.preventDefault();if(overlay)overlay='';else overlay='journal'}if(k==='m')overlay=overlay==='map'?'':'map';if(k==='i')overlay=overlay==='party'?'':'party';if(k==='e'||k==='enter'){if(mode==='title')startGame();else if(mode==='explore'&&!overlay)interact()}if(mode==='battle'&&!overlay){if(['1','2','3','4'].includes(k))battleAction(+k-1)}});window.addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);
document.querySelectorAll('#touch-controls button').forEach(b=>{const key=b.dataset.key;const on=e=>{e.preventDefault();keys[key]=true},off=e=>{e.preventDefault();keys[key]=false};b.addEventListener('pointerdown',on);b.addEventListener('pointerup',off);b.addEventListener('pointerleave',off);b.addEventListener('pointercancel',off)});
function roundRect(x,y,w,h,r,fill,stroke){ctx.beginPath();ctx.roundRect(x,y,w,h,r);if(fill)ctx.fill();if(stroke)ctx.stroke()}
function text(s,x,y,size=14,color='#f2efdf',align='left',font='DM Sans'){ctx.fillStyle=color;ctx.font=`${size}px "${font}", sans-serif`;ctx.textAlign=align;ctx.textBaseline='middle';ctx.fillText(s,x,y)}
function panel(x,y,w,h,alpha=.88){ctx.fillStyle=`rgba(15,27,34,${alpha})`;roundRect(x,y,w,h,10,true,false);ctx.strokeStyle='#d9d4b333';ctx.lineWidth=1;roundRect(x,y,w,h,10,false,true)}
function bar(x,y,w,h,pct,col){ctx.fillStyle='#10181dbb';roundRect(x,y,w,h,h/2,true,false);ctx.fillStyle=col;roundRect(x,y,Math.max(3,w*clamp(pct,0,1)),h,h/2,true,false)}

