function bar(x,y,w,h,pct,col){ctx.fillStyle='#10181dbb';roundRect(x,y,w,h,h/2,true,false);ctx.fillStyle=col;roundRect(x,y,Math.max(3,w*clamp(pct,0,1)),h,h/2,true,false)}
function interact(){
 const near=shrines.find(s=>Math.abs(player.x-s.x)<75);if(near){checkpoint=near.x;party.forEach(m=>m.hp=m.max);persist();toast('Shrine restored your team • checkpoint set');return}
 const chest=pickups.find(p=>Math.abs(player.x-p.x)<58&&!p.got);if(chest){chest.got=true;if(chest.id==='shard'){shards++;toast('Found a Prism Shard +1')}else{coins+=35;essence+=12;toast('Cache found • 35 coins • 12 essence')}persist();return}
 const gate=gates.find(g=>Math.abs(player.x-g.x)<100);if(gate&&!unlocks[gate.kind]){toast(gate.kind==='dash'?'A wind seal. Find the guardian beyond the cavern.':'Root seal. Something heavy will break it.');return}
 if(player.x>3470&&!wonBoss){startBattle('hollow',true);return}
 if(player.x<60){toast('The trail leads east. Find your first wild kin.');return}
 toast('The wilds rustle nearby…')
}
function saveSnapshot(){persist()}
let battle=null;
function startBattle(id,boss=false){const enemyId=id||pick(['mossling','cinderkit','tidepup','gloamoth','craglet']);battle={enemy:makeMon(enemyId,boss?4:Math.max(1,Math.floor(player.x/800)+1)),boss,turn:'player',message:boss?'The Hollow Stag guards the heart of the wilds!':`A wild ${species[enemyId].name} appeared!`,chain:0,defending:false,acting:false};battle.enemy.hp=boss?battle.enemy.max:battle.enemy.max;mode='battle';seen[enemyId]=true;if(!bestiary.includes(enemyId))bestiary.push(enemyId);toast('A wild creature challenges you!')}
function activeMon(){return party.find(m=>m.hp>0)}
function battleAction(index){if(!battle||battle.turn!=='player'||battle.acting)return;const mon=activeMon();if(!mon){battle.message='Your team is exhausted…';return}if(index===3){if(battle.boss){battle.message='You cannot flee the sanctuary guardian!';return}if(Math.random()<.72){mode='explore';player.x=Math.max(80,player.x-90);battle=null;toast('You slipped away safely.');return}battle.message='No escape!';battle.turn='enemy';setTimeout(enemyTurn,700);return}if(index===2){if(shards<=0){battle.message='No Prism Shards left!';return}if(battle.boss){battle.message='The ancient guardian cannot be tamed.';return}shards--;let chance=.28+(1-battle.enemy.hp/battle.enemy.max)*.55;if(Math.random()<chance){const caught={...makeMon(battle.enemy.id||speciesId(battle.enemy.name),Math.max(1,battle.enemy.level)),hp:battle.enemy.hp};if(party.length<3){party.push(caught);battle.message=`${caught.name} joined your team!`}else{coins+=20;battle.message=`${caught.name} sent to the grove • +20 coins`}setTimeout(()=>endBattle(true),1000)}else{battle.message=`${battle.enemy.name} broke free!`;battle.turn='enemy';setTimeout(enemyTurn,850)}return}
battle.acting=true;const e=battle.enemy;const mult=index===1?1.7:1;const damage=Math.round(mon.atk*mult*rand(.87,1.14)*(typeBonus(mon.type,e.type)));e.hp=Math.max(0,e.hp-damage);battle.chain++;battle.message=index===1?`${mon.skill}! ${damage} damage`:`${mon.name} strikes for ${damage}`;if(e.hp<=0){setTimeout(()=>endBattle(false),750);return}battle.turn='enemy';setTimeout(enemyTurn,850)}
function speciesId(name){return Object.keys(species).find(id=>species[id].name===name)||'mossling'}
function typeBonus(a,b){if((a==='Ember'&&b==='Verdant')||(a==='Verdant'&&b==='Tide')||(a==='Tide'&&b==='Ember')||(a==='Gloam'&&b==='Stone')||(a==='Stone'&&b==='Ember'))return 1.35;if((a==='Verdant'&&b==='Ember')||(a==='Tide'&&b==='Verdant')||(a==='Ember'&&b==='Tide')||(a==='Stone'&&b==='Gloam'))return .72;return 1}
function enemyTurn(){if(mode!=='battle'||!battle)return;const target=activeMon();if(!target){battle.message='Your team has fallen…';setTimeout(()=>{party.forEach(m=>m.hp=Math.max(1,Math.round(m.max*.45)));player.x=checkpoint;mode='explore';battle=null;toast('Your team was carried to the last shrine.');persist()},900);return}const damage=Math.max(5,Math.round(battle.enemy.atk*rand(.75,1.1)));target.hp=Math.max(0,target.hp-damage);battle.message=`${battle.enemy.name} hits ${target.name} for ${damage}!`;battle.turn='player';battle.acting=false;if(!activeMon()){battle.message='Your team has fallen…';setTimeout(enemyTurn,700)}}
function endBattle(caught){if(!battle)return;const boss=battle.boss;if(!caught){coins+=boss?140:12+Math.floor(Math.random()*9);essence+=boss?65:5+Math.floor(Math.random()*6);party.forEach(m=>{if(m.hp>0){m.xp+=boss?60:18;if(m.xp>=40+m.level*12){m.xp=0;m.level++;m.max+=10;m.atk+=2;m.hp=m.max;toast(`${m.name} reached level ${m.level}!`)} }});}if(boss){wonBoss=true;unlocks.dash=true;unlocks.break=true;essence+=45;toast('Sanctuary restored • Windstep & Rootbreak unlocked!')}mode='explore';battle=null;player.x=boss?3750:player.x;persist();if(caught)toast('Your new companion is ready!');else if(!boss)toast('Victory • coins and essence earned')}
function update(dt){worldTime+=dt;if(toastTimer){}if(mode==='explore'&&!overlay)updateWorld(dt);if(mode==='battle'&&battle){}if(shake>0)shake=Math.max(0,shake-dt*20)}
function updateWorld(dt){const p=player;let speed=190;if(keys.shift&&unlocks.dash)speed=280;let move=0;if(keys.a||keys.arrowleft||keys.left)move--;if(keys.d||keys.arrowright||keys.right)move++;if(move){p.x+=move*speed*dt;p.dir=move;save.facing=move}p.x=clamp(p.x,0,worldW-34);if((keys[' ']||keys.w||keys.arrowup||keys.jump)&&p.onGround){p.vy=-410;p.onGround=false}if(unlocks.dash&&keys.shift&&move){p.x+=move*260*dt}
p.vy+=1000*dt;p.y+=p.vy*dt;const bottom=groundY;let ground=bottom;for(const s of solids){if(p.x+25>s.x&&p.x<s.x+s.w&&p.y+35<=bottom&&p.y+35>=bottom-s.h&&p.vy>=0)ground=Math.min(ground,bottom-s.h)}if(p.y+34>=ground){p.y=ground-34;p.vy=0;p.onGround=true}else p.onGround=false;
for(const g of gates){if(!unlocks[g.kind]&&Math.abs(p.x-g.x)<20){p.x=g.x+(p.x<g.x?-20:20);p.vy=0}}
for(const pickup of pickups){if(!pickup.got&&Math.abs(p.x-pickup.x)<22&&p.y>groundY-70){pickup.glow=(pickup.glow||0)+dt}}
if(p.x>3470&&!wonBoss&&keys.e)interact();
if(Math.random()<dt*.22&&p.x>240&&p.x<3410&&!battle&&Math.random()<.04)startBattle();
if(Math.floor(p.x/360)!==save.lastZone){save.lastZone=Math.floor(p.x/360);persist()}}

